with with_last as (select s.*, x.account_opened_date, x.status from customers s join lateral (select c.opened_date as account_opened_date, c.status from accounts c where c.customer_id = s.id order by c.balance desc, c.id desc limit 1) x on true) select date_trunc('month', account_opened_date) as activity_month, country, city, approx_percentile(age, 0.5) as age_p50, min(credit_limit) as min_credit_limit, bit_and(age) as age_bit_and, rank() over (partition by date_trunc('month', account_opened_date) order by bit_and(age) desc) as age_bit_and_rank from with_last group by date_trunc('month', account_opened_date), country, city order by city desc nulls last;
